#!/usr/bin/env python3
"""Normalize resolved Python license metadata and create auditable CI evidence."""
from __future__ import annotations

import json
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
FILES = {
    "Local Engine": ROOT / "licenses-local-engine.json",
    "Cloud Engine": ROOT / "licenses-cloud-engine.json",
    "Social Resolver": ROOT / "licenses-social-resolver.json",
}
OVERRIDES = ROOT / ".github" / "license-overrides.json"
REPORT = ROOT / "dependency-license-report.md"
SUMMARY = ROOT / "license-audit-summary.json"


def norm(value: str) -> str:
    return re.sub(r"[-_.]+", "-", value.strip().lower())


def cell(value: object) -> str:
    return str(value or "").replace("|", "\\|").replace("\n", " ").strip()


def main() -> int:
    overrides = json.loads(OVERRIDES.read_text(encoding="utf-8"))
    all_rows: list[dict[str, str]] = []
    unresolved: list[dict[str, str]] = []
    counts: dict[str, int] = {}

    for environment, path in FILES.items():
        if not path.exists():
            raise SystemExit(f"[FAIL] Missing license inventory: {path.name}")
        entries = json.loads(path.read_text(encoding="utf-8"))
        if not isinstance(entries, list):
            raise SystemExit(f"[FAIL] Expected a JSON list in {path.name}")
        counts[environment] = len(entries)
        for entry in entries:
            name = str(entry.get("Name", "")).strip()
            key = norm(name)
            override = next(
                (value for package, value in overrides.items() if norm(package) == key),
                None,
            )
            if override:
                entry["License"] = override["license"]
                entry["LicenseSource"] = override["source"]
                entry["AuditNote"] = override["note"]

            license_name = str(entry.get("License") or "").strip()
            if not license_name or license_name.upper() in {
                "UNKNOWN", "UNKNOWN LICENSE", "LICENSE UNKNOWN", "NONE"
            }:
                unresolved.append({
                    "environment": environment,
                    "name": name,
                    "version": str(entry.get("Version", "")),
                    "url": str(entry.get("URL", "")),
                })
            all_rows.append({
                "environment": environment,
                "name": name,
                "version": str(entry.get("Version", "")),
                "license": license_name or "UNKNOWN",
                "url": str(entry.get("URL", "")),
                "note": str(entry.get("AuditNote", "")),
            })
        path.write_text(json.dumps(entries, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")

    lines = [
        "# Resolved Python dependency license inventory",
        "",
        "Generated by CI from the installed dependency environments. This report describes package metadata; it is not a substitute for checking upstream license texts when redistributing binaries.",
        "",
        "| Environment | Packages |",
        "|---|---:|",
    ]
    lines.extend(f"| {cell(env)} | {count} |" for env, count in counts.items())
    lines += [
        "",
        "## Package-level inventory",
        "",
        "| Environment | Package | Version | Declared license | Metadata URL | Audit note |",
        "|---|---|---|---|---|---|",
    ]
    for row in sorted(all_rows, key=lambda item: (item["environment"], item["name"].lower())):
        lines.append(
            "| " + " | ".join(cell(row[key]) for key in
            ("environment", "name", "version", "license", "url", "note")) + " |"
        )
    lines += [
        "",
        "## Separate manual-review item",
        "",
        "The optional GRIB profile in requirements-grib-optional.txt is excluded from the default Local Engine environment. Its ecCodes/eckit binary wheels may contain additional bundled copyleft components; review the exact platform wheel notices and source obligations before redistributing a container or binary bundle that includes this optional profile.",
        "",
        "The optional GRIB caveat does not mean the default profiles include those packages.",
        "",
    ]
    REPORT.write_text("\n".join(lines), encoding="utf-8")

    summary = {
        "schema_version": 1,
        "inventories": counts,
        "total_package_entries": len(all_rows),
        "unresolved_license_metadata_count": len(unresolved),
        "unresolved_license_metadata": unresolved,
        "manual_review_items": [
            {
                "scope": "optional GRIB profile",
                "packages": ["cfgrib", "eccodes", "eccodeslib", "eckitlib"],
                "status": "excluded from default profile; review required before redistributing a bundle that includes it",
            }
        ],
        "default_python_profiles_license_metadata": "pass" if not unresolved else "fail",
    }
    SUMMARY.write_text(json.dumps(summary, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")

    if unresolved:
        print(f"[FAIL] {len(unresolved)} package entries have unresolved license metadata:")
        for item in unresolved:
            print(f"  - {item['environment']}: {item['name']} {item['version']} ({item['url']})")
        return 1

    print(f"[OK] Resolved license metadata for {len(all_rows)} package entries across {len(FILES)} environments.")
    print("[NOTE] Optional GRIB binary redistribution remains a separately documented manual-review item.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
